"""Langfuse trace vocabulary shared across the builder's telemetry modules.

Span names and tags are the identifiers people search and filter Langfuse by,
so they are contract, not incidental strings: renaming one orphans every saved
view and dashboard built on it. They live here, away from the code that emits
them, so the whole vocabulary is readable at once and a rename is one edit.

Deliberately import-free: the Copilot v2 agent reads from this module, and a
leaf with no imports can never close a cycle or drag an optional dependency
(``langfuse``, ``pydantic-ai``) into a caller that does not have it.
"""

# Root span of one Copilot v2 turn, opened by the web layer. Every pydantic-ai
# span the turn emits — agent run, model requests, tool calls — parents to it.
COPILOT_V2_TRACE_NAME = "copilot_v2"

# Name of the Copilot v2 pydantic-ai agent. At instrumentation version 3+ this
# lands in the agent-run span's name (``"invoke_agent copilot_v2_agent"``) as
# well as its ``gen_ai.agent.name`` attribute; below 3 the span is named by a
# fixed literal and this only reaches the attribute. Correct only in tandem
# with COPILOT_V2_INSTRUMENTATION_VERSION below.
COPILOT_V2_AGENT_NAME = "copilot_v2_agent"

# Data-format version for the GenAI spans pydantic-ai emits, pinned so a
# library bump cannot silently change the wire format Langfuse ingests.
#
# 3 is the lowest version worth using. Versions 1-2 name every tool span the
# same fixed ``"running tool"`` literal and report tool payloads under legacy
# pre-semconv keys (``tool_arguments``/``tool_response``); 3 puts the tool name
# in the span name (``"execute_tool search_rasa_documentation"``) and switches
# to ``gen_ai.tool.call.arguments``/``.result``, which is what Langfuse's
# OpenTelemetry ingestion reads. It also adds thinking-token reporting, which
# matters because Copilot v2 exposes reasoning.
#
# Verified that 4 and 5 emit an identical span tree and attribute set for this
# agent: 4 only adds multimodal content conventions (v2 sends no media) and 5
# only stops marking deferred-tool spans as errors (v2 defers no tools).
COPILOT_V2_INSTRUMENTATION_VERSION = 3

# Tag on every Copilot v2 trace. Shares its value with the trace name but is a
# separate identifier: v1 and v2 turns land in one Langfuse project under one
# session-id scheme, and this tag is what separates them in a filter.
COPILOT_V2_TRANSPORT_TAG = "copilot_v2"

# Tag on any turn that ended in an error. Shared vocabulary: v1's endpoint
# telemetry tags failed traces with the same literal.
ERROR_TAG = "error"

# Root span of one auto-analysis run, opened by the job owner. Deliberately
# distinct from COPILOT_V2_TRACE_NAME: an analysis sends the whole training log
# plus every changed file as instructions, so its token profile differs from an
# interactive turn's by orders of magnitude. Sharing a trace name would corrupt
# per-turn cost and latency aggregates in both directions.
COPILOT_V2_ANALYSIS_TRACE_NAME = "copilot_v2_auto_analysis"

# Name of the auto-analysis agent. At COPILOT_V2_INSTRUMENTATION_VERSION 3+ this
# lands in the agent-run span's name as well as its ``gen_ai.agent.name``
# attribute, so the two v2 agents stay distinguishable inside a trace and not
# only across traces.
COPILOT_V2_ANALYSIS_AGENT_NAME = "copilot_v2_analysis_agent"

# Tag on every auto-analysis trace. Carried alongside COPILOT_V2_TRANSPORT_TAG
# rather than instead of it: these are Copilot v2 runs too, and a filter on the
# transport tag should still find them.
AUTO_ANALYSIS_TAG = "auto_analysis"
